```json
{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS c FROM abnormal_logs WHERE service_name = 'ts-train-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2,3 ORDER BY c DESC",
          "claim": "Train-service logs JDBC connection failures: Communications link failure, Hikari pool timeouts, and Unable to acquire JDBC Connection."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, metric, round(avg(sum/NULLIF(count,0)),1) AS avg_v FROM abnormal_metrics_histogram WHERE service_name='ts-train-service' AND metric LIKE 'db.client.connections%' GROUP BY 1,2 UNION ALL SELECT 'norm', metric, round(avg(sum/NULLIF(count,0)),1) FROM normal_metrics_histogram WHERE service_name='ts-train-service' AND metric LIKE 'db.client.connections%' GROUP BY 1,2",
          "claim": "Train-service DB connection wait and create times rise from about 0.2 ms to 22,500 ms and 30,000 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND attr_span_kind IN ('Server','Internal') GROUP BY 1,2,3 ORDER BY p95_ms DESC",
          "claim": "Train-service server and SQL spans now take about 30 seconds at p95, with no CPU saturation on the pod."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller_svc, c.service_name AS callee_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name GROUP BY 1,2 ORDER BY callee_p95_ms DESC LIMIT 20",
          "claim": "ts-basic-service calls ts-train-service; train's server spans take about 30 s, and basic's POST spans time out at 60 s."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
