          "claim": "ts-travel-service calls ts-basic-service, whose server span now takes about 60 s at p95."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller_svc, c.service_name AS callee_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name GROUP BY 1,2 ORDER BY callee_p95_ms DESC LIMIT 20",
          "claim": "ts-route-plan-service calls ts-travel-service, whose server span takes about 60 s at p95."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller_svc, c.service_name AS callee_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name GROUP BY 1,2 ORDER BY callee_p95_ms DESC LIMIT 20",
          "claim": "ts-travel-plan-service calls ts-route-plan-service, whose server span takes about 61.8 s at p95."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller_svc, c.service_name AS callee_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name GROUP BY 1,2 ORDER BY callee_p95_ms DESC LIMIT 20",
          "claim": "ts-ui-dashboard calls ts-travel-plan-service; the travel-plan server span takes about 60 s at p95."
        }
